/// The filter's error constant: E · (1 + 2u)^4 with E = 48u + 184u^2 + 224u^3 + 136u^4 + 48u^5 +
/// 8u^6, the result's unit error (header), rounded up to an `f64`: 6755399441055753 · 2^-100.
const ERROR: f64 = f64::from_bits(0x3cf8_0000_0000_0009);

/// `ssi_side`'s sign from its `f64` filter, or `None` when the filter's bound cannot certify it.
///
/// `Some(Sign::Zero)` only when the scale is zero, which makes the exact value zero.
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn filter(a: P2, b: P2, c: P2, d: P2, p: P2, q: P2) -> Option<Sign> {
    let dc_x = exact_f64(d.x) - exact_f64(c.x);
    let dc_y = exact_f64(d.y) - exact_f64(c.y);
    let ac_x = exact_f64(a.x) - exact_f64(c.x);
    let ac_y = exact_f64(a.y) - exact_f64(c.y);
    let bc_x = exact_f64(b.x) - exact_f64(c.x);
    let bc_y = exact_f64(b.y) - exact_f64(c.y);
    let qp_x = exact_f64(q.x) - exact_f64(p.x);
    let qp_y = exact_f64(q.y) - exact_f64(p.y);
    let ap_x = exact_f64(a.x) - exact_f64(p.x);
    let ap_y = exact_f64(a.y) - exact_f64(p.y);
    let bp_x = exact_f64(b.x) - exact_f64(p.x);
    let bp_y = exact_f64(b.y) - exact_f64(p.y);
    let oa_1 = dc_x * ac_y;
    let oa_2 = dc_y * ac_x;
    let oa = oa_1 - oa_2;
    let ob_1 = dc_x * bc_y;
    let ob_2 = dc_y * bc_x;
    let ob = ob_1 - ob_2;
    let oa2_1 = qp_x * ap_y;
    let oa2_2 = qp_y * ap_x;
    let oa2 = oa2_1 - oa2_2;
    let ob2_1 = qp_x * bp_y;
    let ob2_2 = qp_y * bp_x;
    let ob2 = ob2_1 - ob2_2;
    let s_1 = oa * ob2;
    let s_2 = ob * oa2;
    let s = s_1 - s_2;
    let m_x = largest_magnitude([dc_x, ac_x, bc_x, qp_x, ap_x, bp_x]);
    let m_y = largest_magnitude([dc_y, ac_y, bc_y, qp_y, ap_y, bp_y]);
    let scale = m_x * m_x * m_y * m_y;
    decide(s, ERROR, scale)
}

/// `ssi_side`'s exact value: each step in the type its certificate gives it, with checked
/// arithmetic; `None` only if a step overflowed, which the certificate rules out.
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn value(a: P2, b: P2, c: P2, d: P2, p: P2, q: P2) -> Option<I256> {
    let dc_x = d.x.get().checked_sub(c.x.get())?;
    let dc_y = d.y.get().checked_sub(c.y.get())?;
    let ac_x = a.x.get().checked_sub(c.x.get())?;
    let ac_y = a.y.get().checked_sub(c.y.get())?;
    let bc_x = b.x.get().checked_sub(c.x.get())?;
    let bc_y = b.y.get().checked_sub(c.y.get())?;
    let qp_x = q.x.get().checked_sub(p.x.get())?;
    let qp_y = q.y.get().checked_sub(p.y.get())?;
    let ap_x = a.x.get().checked_sub(p.x.get())?;
    let ap_y = a.y.get().checked_sub(p.y.get())?;
    let bp_x = b.x.get().checked_sub(p.x.get())?;
    let bp_y = b.y.get().checked_sub(p.y.get())?;
    let oa_1 = i128::from(dc_x).checked_mul(i128::from(ac_y))?;
    let oa_2 = i128::from(dc_y).checked_mul(i128::from(ac_x))?;
    let oa = oa_1.checked_sub(oa_2)?;
    let ob_1 = i128::from(dc_x).checked_mul(i128::from(bc_y))?;
    let ob_2 = i128::from(dc_y).checked_mul(i128::from(bc_x))?;
    let ob = ob_1.checked_sub(ob_2)?;
    let oa2_1 = i128::from(qp_x).checked_mul(i128::from(ap_y))?;
    let oa2_2 = i128::from(qp_y).checked_mul(i128::from(ap_x))?;
    let oa2 = oa2_1.checked_sub(oa2_2)?;
    let ob2_1 = i128::from(qp_x).checked_mul(i128::from(bp_y))?;
    let ob2_2 = i128::from(qp_y).checked_mul(i128::from(bp_x))?;
    let ob2 = ob2_1.checked_sub(ob2_2)?;
    let s_1 = I256::from_i128(oa).checked_mul(&I256::from_i128(ob2))?;
    let s_2 = I256::from_i128(ob).checked_mul(&I256::from_i128(oa2))?;
    let s = s_1.checked_sub(&s_2)?;
    Some(s)
}

/// `ssi_side`'s exact sign: the sign of [`value`], or `None` as for [`value`].
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    reason = "one-letter names are the description's points"
)]
pub fn exact(a: P2, b: P2, c: P2, d: P2, p: P2, q: P2) -> Option<Sign> {
    value(a, b, c, d, p, q).map(|v| v.signum())
}
